import 'package:dartz/dartz.dart';import 'package:dio/dio.dart';import '../../../../../Core/Storage/Remote/api_error_handler.dart';import '../../data/entities/login_model.dart';import '../../data/entities/register_model.dart';import '../../data/entities/user_data_model.dart';import '../../data/repositories/authentication.dart';import '../../data/sources/authentication_sources.dart';class AuthenticationRepoImpl extends AuthenticationRepo {  @override  Future<Either<Failure, UserDataModel>> loginByEmail(      LoginModel loginModel) async {    try {      final response = await getUserDataByEmail(loginModel);      return right(response);    } catch (e) {      if (e is DioException) {        return left(ServerFailure.fromDioError(e));      } else {        return left(ServerFailure.fromResponse(e.hashCode, e));      }    }  }  @override  Future<Either<Failure, bool>> registerByGoogle(      RegisterModel registerModel) async {    try {      final response = await createAccount(registerModel);      return right(response);    } catch (e) {      if (e is DioException) {        return left(ServerFailure.fromDioError(e));      } else {        return left(ServerFailure.fromResponse(e.hashCode, e));      }    }  }}